"use client";

import * as React from "react";
import styles from "../styles/liquid-glass-card.module.css";

export interface LiquidGlassCardProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Card title */
  title?: string;
  /** Supporting copy */
  description?: string;
  /** Backdrop blur radius in pixels */
  blurPx?: number;
  /** Pointer rim highlight intensity */
  rimIntensity?: number;
  /** Translucent background tint */
  surfaceTint?: string;
}

export function LiquidGlassCard({
  title = "Layered Specular Translucency",
  description = "Combines CSS backdrop-filter blur, pointer-tracked rim illumination, and subtle surface sheen with graceful browser fallbacks.",
  blurPx = 16,
  rimIntensity = 0.26,
  surfaceTint = "rgba(24, 24, 32, 0.72)",
  children,
  className = "",
  ...rest
}: LiquidGlassCardProps) {
  const cardRef = React.useRef<HTMLDivElement>(null);

  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    const el = cardRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    el.style.setProperty("--mf-lg-x", `${e.clientX - rect.left}px`);
    el.style.setProperty("--mf-lg-y", `${e.clientY - rect.top}px`);
    el.style.setProperty("--mf-lg-active", "1");
  };

  const handlePointerLeave = () => {
    cardRef.current?.style.setProperty("--mf-lg-active", "0");
  };

  return (
    <div
      ref={cardRef}
      onPointerMove={handlePointerMove}
      onPointerLeave={handlePointerLeave}
      style={
        {
          "--mf-lg-blur": `${blurPx}px`,
          "--mf-lg-rim": rimIntensity,
          "--mf-lg-tint": surfaceTint,
        } as React.CSSProperties
      }
      className={`${styles.card} ${className}`.trim()}
      {...rest}
    >
      <div aria-hidden="true" className={styles.specularSheen} />
      <div aria-hidden="true" className={styles.edgeHighlight} />
      <div className={styles.inner}>
        <span className={styles.eyebrow}>CSS Translucency + Rim Sheen</span>
        <h3 className={styles.title}>{title}</h3>
        <p className={styles.description}>{description}</p>
        {children}
      </div>
    </div>
  );
}

.card {
  --mf-lg-x: 50%;
  --mf-lg-y: 30%;
  --mf-lg-active: 0;
  position: relative;
  overflow: hidden;
  border-radius: 0.9rem;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background-color: var(--mf-lg-tint, rgba(24, 24, 32, 0.72));
  backdrop-filter: blur(var(--mf-lg-blur, 16px)) saturate(140%);
  -webkit-backdrop-filter: blur(var(--mf-lg-blur, 16px)) saturate(140%);
  padding: 1.5rem;
  color: var(--mf-fg, #f4f4f6);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.18), 0 16px 36px rgba(0, 0, 0, 0.45);
}

.specularSheen {
  pointer-events: none;
  position: absolute;
  inset: 0;
  opacity: calc(var(--mf-lg-active, 0) * var(--mf-lg-rim, 0.26));
  transition: opacity 220ms ease;
  background: radial-gradient(
    280px circle at var(--mf-lg-x, 50%) var(--mf-lg-y, 30%),
    rgba(255, 255, 255, 0.75),
    transparent 70%
  );
}

.edgeHighlight {
  pointer-events: none;
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.12) 0%, transparent 45%, rgba(255, 255, 255, 0.04) 100%);
}

.inner {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.eyebrow {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--mf-fg, #d4d4d8);
}

.title {
  margin: 0;
  font-size: 1.05rem;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.description {
  margin: 0;
  font-size: 0.85rem;
  line-height: 1.55;
  color: var(--mf-fg, #d4d4d8);
}

@media (prefers-reduced-motion: reduce) {
  .specularSheen {
    transition: none;
  }
}

